INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(775722, 85243, 8159, '<td valign="top">Typically a newspaper photo of a "signing event" would highlight the person doing the signing, and not the document they are signing -- the story that goes along with the photo would explain all that. So to me,  this seems a bit unrealistic for a newspaper photo.</td>', 'Typically a newspaper photo of a "signing event" would highlight the person doing the signing, and not the document they are signing -- the story that goes along with the photo would explain all that. So to me,  this seems a bit unrealistic for a newspaper photo.', '2004-06-23 10:40:21.000000', NULL, 1),
