INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(776083, 84954, 16488, '<td valign="top">Neat artsy shot.  Is it done in infrared?  Hope you''ll share after the challenge.  Not sure how  or if a newspaper would publish this as news photos not only have to grab the attention but also convey a story and entice the reader to read.</td>', 'Neat artsy shot.  Is it done in infrared?  Hope you''ll share after the challenge.  Not sure how  or if a newspaper would publish this as news photos not only have to grab the attention but also convey a story and entice the reader to read.', '2004-06-23 13:45:27.000000', NULL, 1),
(776084, 85335, 23104, '<td valign="top">very nice mug shot. classic look of a criminal</td>', 'very nice mug shot. classic look of a criminal', '2004-06-23 13:46:23.000000', NULL, 1),
(776085, 84705, 18194, '<td valign="top">This would be a very good photo if it were not so dark. Just a little bit of editing could have done wonder for this photo and no doubt given it a much higher score.</td>', 'This would be a very good photo if it were not so dark. Just a little bit of editing could have done wonder for this photo and no doubt given it a much higher score.', '2004-06-23 13:46:27.000000', NULL, 1),
(776086, 85122, 22922, '<td valign="top">Too dark, but nice combo of headline and image.</td>', 'Too dark, but nice combo of headline and image.', '2004-06-23 13:46:31.000000', NULL, 1),
(776087, 85171, 23104, '<td valign="top">good contrast.</td>', 'good contrast.', '2004-06-23 13:47:06.000000', NULL, 1),
(776088, 85017, 16488, '<td valign="top">The subject is certainly appropriate, but the quality of the photo is not.  There''s too little information in the upper portion of the shot and the images on the screens are blown out.  Focus and contrast would need to be greatly improved to make it into print.</td>', 'The subject is certainly appropriate, but the quality of the photo is not.  There''s too little information in the upper portion of the shot and the images on the screens are blown out.  Focus and contrast would need to be greatly improved to make it into print.', '2004-06-23 13:47:50.000000', NULL, 1),
(776089, 84205, 19035, '<td valign="top">Nice photo - but the picture is too small.</td>', 'Nice photo - but the picture is too small.', '2004-06-23 13:49:55.000000', NULL, 1),
(776091, 84205, 18194, '<td valign="top">way too small and a bit blurry</td>', 'way too small and a bit blurry', '2004-06-23 13:50:17.000000', NULL, 1),
(776092, 85175, 16488, '<td valign="top">Funny shot.  I think it would be better with a tighter cropping--the woman in the background competes for attention with the subject of your shot.  Really neat sculpture, I look forward to learning where it is after the challenge.</td>', 'Funny shot.  I think it would be better with a tighter cropping--the woman in the background competes for attention with the subject of your shot.  Really neat sculpture, I look forward to learning where it is after the challenge.', '2004-06-23 13:50:18.000000', NULL, 1),
(776096, 84585, 19035, '<td valign="top">I love the look on their faces, this photo is great!  I give you a 9.</td>', 'I love the look on their faces, this photo is great!  I give you a 9.', '2004-06-23 13:51:15.000000', NULL, 1),
(776097, 84815, 16488, '<td valign="top">This is a nice image.  I like your treatment of the "For Sale" sign.  I think you should crop to straighten the horizon line. There is also a lack of contrast in the foreground weeds which, under different editing rules, might be enhanced.</td>', 'This is a nice image.  I like your treatment of the "For Sale" sign.  I think you should crop to straighten the horizon line. There is also a lack of contrast in the foreground weeds which, under different editing rules, might be enhanced.', '2004-06-23 13:53:00.000000', NULL, 1),
(776099, 84374, 18194, '<td valign="top">Out of focus.  Also this is a real reach for being a newspaper photo.</td>', 'Out of focus.  Also this is a real reach for being a newspaper photo.', '2004-06-23 13:53:34.000000', NULL, 1),
(776103, 84636, 22061, '<td valign="top">beautiful background color contrast and depth for a sports shot.</td>', 'beautiful background color contrast and depth for a sports shot.', '2004-06-23 13:56:15.000000', NULL, 1),
(776104, 85007, 16488, '<td valign="top">This would make a nice shot for a feature story--perhaps not as the lead photo but as part of a series in a photo story.  There is lack of contrast in the man''s jacket and the whites are overexposed on the cake--tough subjects to capture well in a frame.  Can''t tell you how to cope with the problem, though, as I often run into it myself.</td>', 'This would make a nice shot for a feature story--perhaps not as the lead photo but as part of a series in a photo story.  There is lack of contrast in the man''s jacket and the whites are overexposed on the cake--tough subjects to capture well in a frame.  Can''t tell you how to cope with the problem, though, as I often run into it myself.', '2004-06-23 13:56:53.000000', NULL, 1),
(776105, 84692, 19035, '<td valign="top">Looks like a mode train set, is it?</td>', 'Looks like a mode train set, is it?', '2004-06-23 13:57:45.000000', NULL, 1),
