(776849, 84361, 4226, '<td valign="top">Great capture</td>', 'Great capture', '2004-06-23 20:34:23.000000', NULL, 1),
(776852, 85317, 12573, '<td valign="top">Good effort.  I wish the image was just a bit sharper.  The depth of field is really, really good and looks like the work of a professional.  Lighting for this kind of shot is so difficult, but you''ve pulled it off wonderfully.  7, only because of the lack of detail (would be a 9 from me otherwise).</td>', 'Good effort.  I wish the image was just a bit sharper.  The depth of field is really, really good and looks like the work of a professional.  Lighting for this kind of shot is so difficult, but you''ve pulled it off wonderfully.  7, only because of the lack of detail (would be a 9 from me otherwise).', '2004-06-23 20:37:18.000000', NULL, 1),
(776853, 85283, 12573, '<td valign="top">Not sure what I''m looking at.  I suppose these are truck trailers?  If so, I think a less severe angle on the composition would have been a better approach.  I like the inclusion of the guard rail in the foreground, but the squareness of the rail to the frame flattens the image causing my eye to focus on the railing instead of the truck trailers.<br/> <br/>Edit: multiple misspellings<br/><br/><i>Message edited by author 2004-06-30 20:26:38.</i></td>', 'Not sure what I''m looking at.  I suppose these are truck trailers?  If so, I think a less severe angle on the composition would have been a better approach.  I like the inclusion of the guard rail in the foreground, but the squareness of the rail to the frame flattens the image causing my eye to focus on the railing instead of the truck trailers. Edit: multiple misspellings', '2004-06-23 20:39:49.000000', '2004-06-30 21:26:38.000000', 1),
(776854, 84688, 18194, '<td valign="top">The photo is somewhat on the dark side.  The alien is kind of hard to see.  If you had a photo of a real alien it would be quite a shot, as it is this is not a photo I would expect to see in a newspaper.</td>', 'The photo is somewhat on the dark side.  The alien is kind of hard to see.  If you had a photo of a real alien it would be quite a shot, as it is this is not a photo I would expect to see in a newspaper.', '2004-06-23 20:40:50.000000', NULL, 1),
(776855, 84427, 12573, '<td valign="top">Increased contrast would have helped this image out a lot.  Also, the subject (which is apparently the ferry landing) is lost in the granduer of the cityscape/bridge.  Perhaps getting closer to the ferry landing and using a larger aperature would have made the photo more interesting.</td>', 'Increased contrast would have helped this image out a lot.  Also, the subject (which is apparently the ferry landing) is lost in the granduer of the cityscape/bridge.  Perhaps getting closer to the ferry landing and using a larger aperature would have made the photo more interesting.', '2004-06-23 20:42:09.000000', NULL, 1),
(776858, 84815, 20841, '<td valign="top"></td>', '', '2004-06-23 20:44:00.000000', NULL, 1),
(776859, 84735, 14043, '<td valign="top">This goes in order of what I notice first:<br/>1) Needs a better title...it doesn''t sound like a headline.<br/>2) Crop to the plane and the cloud, we don''t care about the mountains or the sky around it, just the bright yellow plane and the pretty white cloud it''s dropping...<br/>Score: 5</td>', 'This goes in order of what I notice first:1) Needs a better title...it doesn''t sound like a headline.2) Crop to the plane and the cloud, we don''t care about the mountains or the sky around it, just the bright yellow plane and the pretty white cloud it''s dropping...Score: 5', '2004-06-23 20:44:41.000000', NULL, 1),
(776860, 85130, 12573, '<td valign="top">Too little resolution and too much grain.  Also, the highly exposed nature of this picture does not really suit the subject, which is rather dark.  I do like the relationship between the man in the sandals who has just passed and the man begging, but I think the other elements of the image conflict with the story being told there.</td>', 'Too little resolution and too much grain.  Also, the highly exposed nature of this picture does not really suit the subject, which is rather dark.  I do like the relationship between the man in the sandals who has just passed and the man begging, but I think the other elements of the image conflict with the story being told there.', '2004-06-23 20:44:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(776865, 84522, 12573, '<td valign="top">Well, I think I just stumbled onto the blue ribbon winner.  Absolutely fantastic stuff.  If only the jaggies on her shoulder weren''t there.  No matter, I''m sure the original doesn''t have them.  10, 10, 10.</td>', 'Well, I think I just stumbled onto the blue ribbon winner.  Absolutely fantastic stuff.  If only the jaggies on her shoulder weren''t there.  No matter, I''m sure the original doesn''t have them.  10, 10, 10.', '2004-06-23 20:54:34.000000', NULL, 1),
(776869, 85168, 18194, '<td valign="top">I have to say that this looks like a nice photo you got of your kids and then came up with a title to try as best as you could to make it meet the challenge.  I dont think I would classify this as a journalistic shot.  The photo is well done however in terms of lighting and framing.  The background seems a little bit on the cluttered side to me.</td>', 'I have to say that this looks like a nice photo you got of your kids and then came up with a title to try as best as you could to make it meet the challenge.  I dont think I would classify this as a journalistic shot.  The photo is well done however in terms of lighting and framing.  The background seems a little bit on the cluttered side to me.', '2004-06-23 20:56:30.000000', NULL, 1),
(776871, 84636, 12573, '<td valign="top">I have to question the border, but the stopped motion is excellent.  I also, like the DOF with her feet slightly blurry...keeps my eyes in the area of the bar and her face.</td>', 'I have to question the border, but the stopped motion is excellent.  I also, like the DOF with her feet slightly blurry...keeps my eyes in the area of the bar and her face.', '2004-06-23 20:57:53.000000', NULL, 1),
(776873, 85316, 23279, '<td valign="top">That squirrel is just gorgeous.  What a beautiful picture.</td>', 'That squirrel is just gorgeous.  What a beautiful picture.', '2004-06-23 20:58:36.000000', NULL, 1),
(776874, 85138, 18194, '<td valign="top">Well it is a photo of the moon but it is lacking in any real interest, at least more me. The edges of the moon are pretty rough looking and there does not seem to be any real detail in it.  As for being  photo that would be published in a newspaper I just dont see it.</td>', 'Well it is a photo of the moon but it is lacking in any real interest, at least more me. The edges of the moon are pretty rough looking and there does not seem to be any real detail in it.  As for being  photo that would be published in a newspaper I just dont see it.', '2004-06-23 20:58:55.000000', NULL, 1),
(776880, 84064, 18194, '<td valign="top">On the positive side the DOF and focus are good. The subject matter is not one that I would expect to see in a newspaper and not one that is all the interesting, at least to me.  I also find the edge of the sunlight a bit distracting.</td>', 'On the positive side the DOF and focus are good. The subject matter is not one that I would expect to see in a newspaper and not one that is all the interesting, at least to me.  I also find the edge of the sunlight a bit distracting.', '2004-06-23 21:02:25.000000', NULL, 1),
(776883, 84646, 18194, '<td valign="top">Nothing in the photo gives me the feeling that these people are a group, they look like just people crossing a street. For a group that has just been pick for a TV show they look pretty down in the mouth and unhappy.</td>', 'Nothing in the photo gives me the feeling that these people are a group, they look like just people crossing a street. For a group that has just been pick for a TV show they look pretty down in the mouth and unhappy.', '2004-06-23 21:04:35.000000', NULL, 1),
(776884, 85010, 12573, '<td valign="top">Too much use of Neatimage or PS despeckling.  The composition itself is not bad, though the differences in light from the girls in the dugout to the girl on the field is throwing me off a little.</td>', 'Too much use of Neatimage or PS despeckling.  The composition itself is not bad, though the differences in light from the girls in the dugout to the girl on the field is throwing me off a little.', '2004-06-23 21:05:37.000000', NULL, 1),
(776887, 84933, 18194, '<td valign="top">I am sure that this is big news for you but for the rest of us not something we would expect to read about in our morning paper.  In the end it is a photo of a baby standing with nothing to really make it stand out.  For me having the head cropped detracts a bit from the photo.</td>', 'I am sure that this is big news for you but for the rest of us not something we would expect to read about in our morning paper.  In the end it is a photo of a baby standing with nothing to really make it stand out.  For me having the head cropped detracts a bit from the photo.', '2004-06-23 21:06:53.000000', NULL, 1),
(776889, 84285, 10390, '<td valign="top">Very funny!</td>', 'Very funny!', '2004-06-23 21:07:23.000000', NULL, 1),
(776893, 84821, 18194, '<td valign="top">Your title really does not tell me why this photo is in the paper.  Sorry but to me it looks like trying to shoehorn in a sunset photo into a challenge where it really does not fit.</td>', 'Your title really does not tell me why this photo is in the paper.  Sorry but to me it looks like trying to shoehorn in a sunset photo into a challenge where it really does not fit.', '2004-06-23 21:09:07.000000', NULL, 1),
