(777508, 85333, 16241, '<td valign="top">nice</td>', 'nice', '2004-06-24 04:30:57.000000', NULL, 1),
(777509, 84961, 16241, '<td valign="top">abstact, but nice</td>', 'abstact, but nice', '2004-06-24 04:31:53.000000', NULL, 1),
