(777521, 85202, 21158, '<td valign="top">striking...</td>', 'striking...', '2004-06-24 04:42:05.000000', NULL, 1),
(777528, 85322, 21158, '<td valign="top">crop below the beard and lose the border ...6</td>', 'crop below the beard and lose the border ...6', '2004-06-24 04:45:36.000000', NULL, 1),
(777538, 84590, 21158, '<td valign="top">crop to right side of affected car</td>', 'crop to right side of affected car', '2004-06-24 04:58:20.000000', NULL, 1),
(777540, 85158, 9809, '<td valign="top">What a concept. Your Caption matches the photo -- I''m surprised how rare that is in this challenge. Sure. I could buy this as a newspaper photo -- clearly meets the challenge and is a nice execution of a photo.</td>', 'What a concept. Your Caption matches the photo -- I''m surprised how rare that is in this challenge. Sure. I could buy this as a newspaper photo -- clearly meets the challenge and is a nice execution of a photo.', '2004-06-24 04:59:33.000000', NULL, 1),
(777543, 85274, 21158, '<td valign="top">good show...8</td>', 'good show...8', '2004-06-24 05:02:03.000000', NULL, 1),
(777546, 85279, 9809, '<td valign="top">I could buy a caption like "Charity Horse Show at the Fair" but if this is the "Grand Champion" where is the ribbon, trophy, award that shows this as the champion. Your title should match the photo. This photo mostly works, but I''d like to NOT see the guys hand from right and also lose the pickup and trailer in the lower left. The angle, clouds, general framing other than that works great.</td>', 'I could buy a caption like "Charity Horse Show at the Fair" but if this is the "Grand Champion" where is the ribbon, trophy, award that shows this as the champion. Your title should match the photo. This photo mostly works, but I''d like to NOT see the guys hand from right and also lose the pickup and trailer in the lower left. The angle, clouds, general framing other than that works great.', '2004-06-24 05:02:45.000000', NULL, 1),
(777547, 84585, 21158, '<td valign="top">nice photo, not publishable though.......</td>', 'nice photo, not publishable though.......', '2004-06-24 05:04:37.000000', NULL, 1),
(777550, 85055, 21158, '<td valign="top">front page..good shot..9</td>', 'front page..good shot..9', '2004-06-24 05:06:05.000000', NULL, 1),
(777553, 85210, 21158, '<td valign="top">nice pic, but it''s not a yacht.  also crop tighter.</td>', 'nice pic, but it''s not a yacht.  also crop tighter.', '2004-06-24 05:15:55.000000', NULL, 1),
