(777573, 85308, 21158, '<td valign="top">very good. ..8</td>', 'very good. ..8', '2004-06-24 05:29:05.000000', NULL, 1),
(777577, 84678, 23336, '<td valign="top">A cool idea would have been to get somones facial expression when they were looking at an art piece. Kind of like thats interesting, and somehow get the pice of art in the picture too. Somthing like that, but i still like this one.</td>', 'A cool idea would have been to get somones facial expression when they were looking at an art piece. Kind of like thats interesting, and somehow get the pice of art in the picture too. Somthing like that, but i still like this one.', '2004-06-24 05:31:08.000000', NULL, 1),
(777580, 84696, 21158, '<td valign="top">very good. front page.</td>', 'very good. front page.', '2004-06-24 05:32:26.000000', NULL, 1),
(777584, 85279, 21158, '<td valign="top">the hand is in the way. this could have been a 10 if it was just the horse and rider....7</td>', 'the hand is in the way. this could have been a 10 if it was just the horse and rider....7', '2004-06-24 05:34:42.000000', NULL, 1),
(777587, 84429, 23336, '<td valign="top">The picture is sweet, but the newspaper headline is sour, thats like saying ice is cold. good job though.</td>', 'The picture is sweet, but the newspaper headline is sour, thats like saying ice is cold. good job though.', '2004-06-24 05:38:54.000000', NULL, 1),
(777595, 84992, 22011, '<td valign="top">I''d love to see the photo the chap in the foreground is taking :-).</td>', 'I''d love to see the photo the chap in the foreground is taking :-).', '2004-06-24 05:54:36.000000', NULL, 1),
(777596, 85140, 16241, '<td valign="top">nice macro shot</td>', 'nice macro shot', '2004-06-24 05:55:11.000000', NULL, 1),
(777598, 85226, 16241, '<td valign="top">nice in black &amp; white.......</td>', 'nice in black & white.......', '2004-06-24 05:56:26.000000', NULL, 1),
(777601, 85335, 21158, '<td valign="top">all that''s missing is the numbers on his chest.  the light reflection on his nose should have been eliminated..fits the challenge...7</td>', 'all that''s missing is the numbers on his chest.  the light reflection on his nose should have been eliminated..fits the challenge...7', '2004-06-24 05:58:11.000000', NULL, 1),
(777602, 84961, 22011, '<td valign="top">Ths is a really interesting photo, but I can''t see it appearing in a paper with that headline..</td>', 'Ths is a really interesting photo, but I can''t see it appearing in a paper with that headline..', '2004-06-24 05:58:40.000000', NULL, 1),
(777603, 85295, 22011, '<td valign="top">A good match for the challenge, and a well caught shot...</td>', 'A good match for the challenge, and a well caught shot...', '2004-06-24 05:59:48.000000', NULL, 1),
(777604, 85066, 21158, '<td valign="top">headline too long.</td>', 'headline too long.', '2004-06-24 06:02:21.000000', NULL, 1),
