(777607, 85285, 22011, '<td valign="top">:-)</td>', ':-)', '2004-06-24 06:07:39.000000', NULL, 1),
(777609, 84839, 22011, '<td valign="top">:-).</td>', ':-).', '2004-06-24 06:12:57.000000', NULL, 1),
(777611, 85307, 22011, '<td valign="top">The Furry animal shot for this challenge I presume?  The flash is a bit harsh for the pussy, but I assume you''re one of the owners who terrorises their cat? :-)</td>', 'The Furry animal shot for this challenge I presume?  The flash is a bit harsh for the pussy, but I assume you''re one of the owners who terrorises their cat? :-)', '2004-06-24 06:14:35.000000', NULL, 1),
(777612, 85055, 22011, '<td valign="top">I love the expressions!  This is the best sports one I''ve seen so far in this challenge, well caught.</td>', 'I love the expressions!  This is the best sports one I''ve seen so far in this challenge, well caught.', '2004-06-24 06:17:15.000000', NULL, 1),
