(778167, 85313, 20853, '<td valign="top">It doesn''t fit the challenge</td>', 'It doesn''t fit the challenge', '2004-06-24 15:38:40.000000', NULL, 1),
(778170, 84691, 7682, '<td valign="top">Excellent...That''s a magazine cover.  Great framing and color</td>', 'Excellent...That''s a magazine cover.  Great framing and color', '2004-06-24 15:39:50.000000', NULL, 1),
(778171, 84812, 7682, '<td valign="top">Too overexposed</td>', 'Too overexposed', '2004-06-24 15:40:29.000000', NULL, 1),
(778173, 84698, 7682, '<td valign="top">Nice shot but would have rocked w/no blur on the drop</td>', 'Nice shot but would have rocked w/no blur on the drop', '2004-06-24 15:41:10.000000', NULL, 1),
(778174, 85234, 7682, '<td valign="top">Nice shot but should have less sky for a newpaper shot</td>', 'Nice shot but should have less sky for a newpaper shot', '2004-06-24 15:42:43.000000', NULL, 1),
(778179, 84086, 7682, '<td valign="top">Nice, haunting shot but you need a better  title</td>', 'Nice, haunting shot but you need a better  title', '2004-06-24 15:43:52.000000', NULL, 1),
(778185, 84692, 20853, '<td valign="top">This looks fake.  Something doesn''t look right about it, like it''s a model train set.  It doesn''t take away from the score I gave it.  Is this real?</td>', 'This looks fake.  Something doesn''t look right about it, like it''s a model train set.  It doesn''t take away from the score I gave it.  Is this real?', '2004-06-24 15:46:06.000000', NULL, 1),
(778186, 85319, 7682, '<td valign="top">Could have cropped out the water and land, not necessary for the shot</td>', 'Could have cropped out the water and land, not necessary for the shot', '2004-06-24 15:46:25.000000', NULL, 1),
(778188, 84205, 20853, '<td valign="top">small, out of focus, and the photo combined with the title would not be in a newspaper.</td>', 'small, out of focus, and the photo combined with the title would not be in a newspaper.', '2004-06-24 15:48:43.000000', NULL, 1),
(778193, 85326, 20853, '<td valign="top">Excellent headline for this photo.</td>', 'Excellent headline for this photo.', '2004-06-24 15:51:20.000000', NULL, 1),
(778194, 85016, 20853, '<td valign="top">What?</td>', 'What?', '2004-06-24 15:52:15.000000', NULL, 1),
(778199, 85277, 9452, '<td valign="top">¡Hola paisano!, epero hayas disfrutado del concierto y te deseo mucha suerte.<br/>:)</td>', '¡Hola paisano!, epero hayas disfrutado del concierto y te deseo mucha suerte.:)', '2004-06-24 15:56:49.000000', NULL, 1),
(778208, 85307, 20853, '<td valign="top">Nice looking cat.</td>', 'Nice looking cat.', '2004-06-24 16:04:25.000000', NULL, 1),
(778210, 85248, 20853, '<td valign="top">Excellent job capturing the essence of the story.</td>', 'Excellent job capturing the essence of the story.', '2004-06-24 16:05:35.000000', NULL, 1),
(778215, 85228, 6130, '<td valign="top">Great 10</td>', 'Great 10', '2004-06-24 16:08:49.000000', NULL, 1),
(778216, 85263, 6130, '<td valign="top">Just 10</td>', 'Just 10', '2004-06-24 16:09:21.000000', NULL, 1),
(778226, 84636, 9452, '<td valign="top">Excellent! you got the blue one. At least for me...</td>', 'Excellent! you got the blue one. At least for me...', '2004-06-24 16:18:01.000000', NULL, 1),
(778241, 84766, 9747, '<td valign="top">The picture is blurry/jagged which is distracting, but other than that, very nice! Good composition and placement.</td>', 'The picture is blurry/jagged which is distracting, but other than that, very nice! Good composition and placement.', '2004-06-24 16:34:45.000000', NULL, 1),
(778247, 85005, 21367, '<td valign="top">Very cool and a very good shot.  Nice detail and appeal.  I might not have cropped is so tight on the right but would have kept it off center as you have here,  and taken a tad bit off of the left.  Very good shot.</td>', 'Very cool and a very good shot.  Nice detail and appeal.  I might not have cropped is so tight on the right but would have kept it off center as you have here,  and taken a tad bit off of the left.  Very good shot.', '2004-06-24 16:47:01.000000', NULL, 1),
(778248, 85279, 9747, '<td valign="top">Just a few nitpicks: I wish the horse''s snout wasn''t touching the border, the truck in the background is distracting as is the petting hand. Other than those, beautiful horse, lovely rider with a nice smile, and excellent sky. Good one!</td>', 'Just a few nitpicks: I wish the horse''s snout wasn''t touching the border, the truck in the background is distracting as is the petting hand. Other than those, beautiful horse, lovely rider with a nice smile, and excellent sky. Good one!', '2004-06-24 16:47:06.000000', NULL, 1),
(778251, 84585, 22781, '<td valign="top">I Like this. And I am not even American :)<br/>A pitty that the guy is in the background... Voted: High!</td>', 'I Like this. And I am not even American :)A pitty that the guy is in the background... Voted: High!', '2004-06-24 16:49:02.000000', NULL, 1),
(778252, 85295, 21367, '<td valign="top">Good shot, I like this done in b/w.  You captured the moment well.</td>', 'Good shot, I like this done in b/w.  You captured the moment well.', '2004-06-24 16:50:05.000000', NULL, 1),
(778253, 84678, 21412, '<td valign="top">Depth of field not great, but I like the idea</td>', 'Depth of field not great, but I like the idea', '2004-06-24 16:50:14.000000', NULL, 1),
(778254, 85292, 22781, '<td valign="top">Funny, very funny.<br/>Background is a bit distracting.</td>', 'Funny, very funny.Background is a bit distracting.', '2004-06-24 16:50:32.000000', NULL, 1),
(778255, 84619, 21412, '<td valign="top">Looks like a scene from a gothic movie</td>', 'Looks like a scene from a gothic movie', '2004-06-24 16:51:10.000000', NULL, 1),
(778256, 84692, 21978, '<td valign="top">nice model</td>', 'nice model', '2004-06-24 16:51:10.000000', NULL, 1),
(778257, 84086, 22781, '<td valign="top">I like the Photo, just dont get the message, but that could be me. 7</td>', 'I like the Photo, just dont get the message, but that could be me. 7', '2004-06-24 16:51:13.000000', NULL, 1),
(778259, 85170, 21367, '<td valign="top">Very strong shot.  The b/w works well here.  The flowers tells the story that someone has lost their life here and the cameras may not of helped.  Very good shot.</td>', 'Very strong shot.  The b/w works well here.  The flowers tells the story that someone has lost their life here and the cameras may not of helped.  Very good shot.', '2004-06-24 16:53:37.000000', NULL, 1),
(778261, 84821, 22781, '<td valign="top">Nice picture, looks like you could use a tripod.<br/>But, and you heard this over and over, this does not meet the challenge...</td>', 'Nice picture, looks like you could use a tripod.But, and you heard this over and over, this does not meet the challenge...', '2004-06-24 16:54:02.000000', NULL, 1),
(778264, 85202, 22781, '<td valign="top">Nice picture.<br/>But, and you heard this over and over, this does not meet the challenge...</td>', 'Nice picture.But, and you heard this over and over, this does not meet the challenge...', '2004-06-24 16:55:27.000000', NULL, 1),
(778267, 85059, 21367, '<td valign="top">Great shot, I like the tones that you achieved here.   I keep being drawn to the corner of the scale near the top left, I may have cropped right at that point to remove the distraction.  Very good.</td>', 'Great shot, I like the tones that you achieved here.   I keep being drawn to the corner of the scale near the top left, I may have cropped right at that point to remove the distraction.  Very good.', '2004-06-24 16:56:41.000000', NULL, 1),
(778271, 85291, 9747, '<td valign="top">A bit too grainy and there''s too much space - I think it would look better with either a bit of top or left side cropped out. This is an excellent newspaper-ish photograph. Kudos!</td>', 'A bit too grainy and there''s too much space - I think it would look better with either a bit of top or left side cropped out. This is an excellent newspaper-ish photograph. Kudos!', '2004-06-24 17:05:50.000000', NULL, 1),
(778272, 84585, 21978, '<td valign="top">hahaha......good one</td>', 'hahaha......good one', '2004-06-24 17:14:35.000000', NULL, 1),
(778279, 85319, 20539, '<td valign="top">crazy colours! thought of tsaking a shot like this, but without tripod its nearly impossible... 10</td>', 'crazy colours! thought of tsaking a shot like this, but without tripod its nearly impossible... 10', '2004-06-24 17:24:38.000000', NULL, 1),
(778280, 84285, 9747, '<td valign="top">Got a big laugh out of this! Only thing is, it might have been better if the guy is positioned inside the bathroom so that his feet and legs are sticking out across the doorway threshold. Thanks for the laugh, very creative!</td>', 'Got a big laugh out of this! Only thing is, it might have been better if the guy is positioned inside the bathroom so that his feet and legs are sticking out across the doorway threshold. Thanks for the laugh, very creative!', '2004-06-24 17:25:37.000000', NULL, 1),
(778288, 85015, 20779, '<td valign="top">The shot is very clear, but strikes me as a snapshot with no particular point of interest or focal point. The balance of the composition is hurt by the dog being centered and a large gap between him and the background scene. Perhaps it could have been more focused on what the dog did to get "news" attention or something along those lines.</td>', 'The shot is very clear, but strikes me as a snapshot with no particular point of interest or focal point. The balance of the composition is hurt by the dog being centered and a large gap between him and the background scene. Perhaps it could have been more focused on what the dog did to get "news" attention or something along those lines.', '2004-06-24 17:39:41.000000', NULL, 1),
(778292, 85289, 20779, '<td valign="top">This is a cool arrangement, giving a deeper perspective than usual. I wish that the focus was sharper and that something would stand out to get my attention. Just a sharper focus and contrast might provide that. It doesn''t  honestly seem to be a journalistic photo, but I think this challenge is very open to debate and opinion, so I am not basing my scores on that heavily.</td>', 'This is a cool arrangement, giving a deeper perspective than usual. I wish that the focus was sharper and that something would stand out to get my attention. Just a sharper focus and contrast might provide that. It doesn''t  honestly seem to be a journalistic photo, but I think this challenge is very open to debate and opinion, so I am not basing my scores on that heavily.', '2004-06-24 17:43:41.000000', NULL, 1),
(778294, 85016, 14043, '<td valign="top">This goes in order of what I notice first:<br/>1) (First thing that ran through my head) What is that??  Okay, after looking, I get it.<br/>a- A newspaper photo needs to be easily recognizable<br/>b- It needs to focus on the specific subject of the article<br/>2) It''s too cluttered, for whatever you did (some sort of reflection?) it needed a plain background to make it clear.<br/>3) Up the contrast some to bring out the silver in that Mercedes symbol, make it stand out!<br/>Score: 4</td>', 'This goes in order of what I notice first:1) (First thing that ran through my head) What is that??  Okay, after looking, I get it.a- A newspaper photo needs to be easily recognizableb- It needs to focus on the specific subject of the article2) It''s too cluttered, for whatever you did (some sort of reflection?) it needed a plain background to make it clear.3) Up the contrast some to bring out the silver in that Mercedes symbol, make it stand out!Score: 4', '2004-06-24 17:45:28.000000', NULL, 1),
(778295, 84715, 20779, '<td valign="top">I think this is an interesting point of view artistically, but I think that the event/scene of topic would more likely be the focus in a journalistic shot. The shot would be more dramatic with a sharper focus and deeper DOF in my opinion. I would also probably play around with the cropping and whether or not I would want the stripe centered.</td>', 'I think this is an interesting point of view artistically, but I think that the event/scene of topic would more likely be the focus in a journalistic shot. The shot would be more dramatic with a sharper focus and deeper DOF in my opinion. I would also probably play around with the cropping and whether or not I would want the stripe centered.', '2004-06-24 17:46:47.000000', NULL, 1),
(778296, 85335, 20679, '<td valign="top">he looks sinister!</td>', 'he looks sinister!', '2004-06-24 17:47:56.000000', NULL, 1),
(778298, 85313, 20779, '<td valign="top">Cute take on the challenge, but in my opinion, it still seems like a family snapshot to me. For the photograph itself, I think it would be great with a little more color and definition. It appears washed out on my screen. Different croppings might completely change the feeling, also.</td>', 'Cute take on the challenge, but in my opinion, it still seems like a family snapshot to me. For the photograph itself, I think it would be great with a little more color and definition. It appears washed out on my screen. Different croppings might completely change the feeling, also.', '2004-06-24 17:49:13.000000', NULL, 1),
(778305, 85066, 20779, '<td valign="top">I think this challenge is wide open to interpretation, but I think this is really too much of a stretch for me (at least given that "headline"). I really like the colors in the sky, but I am seeing a bit of a blurrry haze on my monitor. It appears that the foreground is "level", but I think I would have leveled the horizon instead. The foreground lacks detail and is very dark, but that may be influenced by my monitor or desired in how you wanted to present this. I would like a little more "interest" to draw me in; right now, the yellow sun on the horizon is the only focus of interest.</td>', 'I think this challenge is wide open to interpretation, but I think this is really too much of a stretch for me (at least given that "headline"). I really like the colors in the sky, but I am seeing a bit of a blurrry haze on my monitor. It appears that the foreground is "level", but I think I would have leveled the horizon instead. The foreground lacks detail and is very dark, but that may be influenced by my monitor or desired in how you wanted to present this. I would like a little more "interest" to draw me in; right now, the yellow sun on the horizon is the only focus of interest.', '2004-06-24 17:54:24.000000', NULL, 1),
(778306, 85190, 21621, '<td valign="top">This one has alot of potential. If you were to shoot from the other side of the street, at closer range, with the police cars in the background, it might allow for a tighter crop, and also the subjects might be more promenently featured.  Also it is slightly out of focus, but overall I like it, good work.</td>', 'This one has alot of potential. If you were to shoot from the other side of the street, at closer range, with the police cars in the background, it might allow for a tighter crop, and also the subjects might be more promenently featured.  Also it is slightly out of focus, but overall I like it, good work.', '2004-06-24 17:54:53.000000', NULL, 1),
(778309, 85251, 20779, '<td valign="top">On my monitor, this appears very dark and fuzzy. I can''t really find a focal point or tie it into the headline/challenge, but that is an opinion only.</td>', 'On my monitor, this appears very dark and fuzzy. I can''t really find a focal point or tie it into the headline/challenge, but that is an opinion only.', '2004-06-24 17:56:19.000000', NULL, 1),
(778310, 84585, 21621, '<td valign="top">Fantastic !!  Unfoutunatly no paper would print this, but that wont stop me from scoring this shot a 10.</td>', 'Fantastic !!  Unfoutunatly no paper would print this, but that wont stop me from scoring this shot a 10.', '2004-06-24 17:59:20.000000', NULL, 1),
(778314, 85313, 20679, '<td valign="top">very cute!</td>', 'very cute!', '2004-06-24 18:02:41.000000', NULL, 1),
(778315, 85312, 20679, '<td valign="top">great shot</td>', 'great shot', '2004-06-24 18:03:31.000000', NULL, 1),
(778318, 85226, 21621, '<td valign="top">Good shot, I might like to see the other view,  but the sun may not have cooperated, also the headline could be tweaked.  Maybe "More homeless turned away from shelters".</td>', 'Good shot, I might like to see the other view,  but the sun may not have cooperated, also the headline could be tweaked.  Maybe "More homeless turned away from shelters".', '2004-06-24 18:08:15.000000', NULL, 1),
(778322, 85287, 20779, '<td valign="top">I enjoy how this shot looks "painted" almost. Probably a lot nicer than photos in the paper! I would love to see the original and see what cropping you did. It absolutely works this way, but there may be other great ways to present this also. If I had to fault the shot at all, I would say that there is no one strong point of "interest", so it doesn''t "grab" you as easily.</td>', 'I enjoy how this shot looks "painted" almost. Probably a lot nicer than photos in the paper! I would love to see the original and see what cropping you did. It absolutely works this way, but there may be other great ways to present this also. If I had to fault the shot at all, I would say that there is no one strong point of "interest", so it doesn''t "grab" you as easily.', '2004-06-24 18:14:35.000000', NULL, 1),
(778327, 85326, 20779, '<td valign="top">Very clear photograph, and certainly meets the challenge. In my opinion, what keeps me from scoring even higher would be the lack of a true subject or focal point, and that it is a bit busy. Very appropriate for a "news" shot, but otherwise, hurts it for me as a photograph.</td>', 'Very clear photograph, and certainly meets the challenge. In my opinion, what keeps me from scoring even higher would be the lack of a true subject or focal point, and that it is a bit busy. Very appropriate for a "news" shot, but otherwise, hurts it for me as a photograph.', '2004-06-24 18:18:53.000000', NULL, 1),
(778329, 85228, 21621, '<td valign="top">Nice shot, might benefit from centering the subject, and showing more detail in the face.  Also I can imagine that those peppers would make a brilliant color photo, but the B&amp;W does fit this challange.  Good work.</td>', 'Nice shot, might benefit from centering the subject, and showing more detail in the face.  Also I can imagine that those peppers would make a brilliant color photo, but the B&W does fit this challange.  Good work.', '2004-06-24 18:20:05.000000', NULL, 1),
(778330, 85008, 20779, '<td valign="top">This does strike me as something you might see in your "local interest" section of the paper. I also like the expression you caught on the man''s face. The two things that keep me personally from going higher is that the flowers seem disportionately large to me and the colors and focus are a bit washed out. While a candid news shot would very likely have glares, etc., as purely a photograph, there are things that could really make this a beautiful shot.</td>', 'This does strike me as something you might see in your "local interest" section of the paper. I also like the expression you caught on the man''s face. The two things that keep me personally from going higher is that the flowers seem disportionately large to me and the colors and focus are a bit washed out. While a candid news shot would very likely have glares, etc., as purely a photograph, there are things that could really make this a beautiful shot.', '2004-06-24 18:22:53.000000', NULL, 1),
(778331, 85293, 21621, '<td valign="top">I like the composition here, but what you needed was the low sun angle of morning or evening to effectively light the statue. Good work.</td>', 'I like the composition here, but what you needed was the low sun angle of morning or evening to effectively light the statue. Good work.', '2004-06-24 18:23:44.000000', NULL, 1),
(778332, 85080, 21362, '<td valign="top">Great action shot -- I could totally see this on the sports page! I have no suggestions, it''s great as it is!</td>', 'Great action shot -- I could totally see this on the sports page! I have no suggestions, it''s great as it is!', '2004-06-24 18:24:35.000000', NULL, 1),
(778335, 84522, 21362, '<td valign="top">One of my top three for this challenge. Great photo, great expression on the girl''s face, great title/photo combo perfectly suited to this challenge. Great all around!</td>', 'One of my top three for this challenge. Great photo, great expression on the girl''s face, great title/photo combo perfectly suited to this challenge. Great all around!', '2004-06-24 18:25:59.000000', NULL, 1),
(778336, 85017, 20779, '<td valign="top">I know how difficult it is to take these kinds of shots, so these are "wishes" to make this better. I think, especially for a journalistic shot, that I would like to be seeing either my audience''s faces or a shot of the performer. It appears very dark with only a few overly bright areas. I wish I could see something clearly on the bright background we''re seeing through the fans.</td>', 'I know how difficult it is to take these kinds of shots, so these are "wishes" to make this better. I think, especially for a journalistic shot, that I would like to be seeing either my audience''s faces or a shot of the performer. It appears very dark with only a few overly bright areas. I wish I could see something clearly on the bright background we''re seeing through the fans.', '2004-06-24 18:26:26.000000', NULL, 1),
(778337, 84704, 21362, '<td valign="top">Very dramatic photo. The silouette is wonderful! Super entry for this challenge! One of my top three picks!</td>', 'Very dramatic photo. The silouette is wonderful! Super entry for this challenge! One of my top three picks!', '2004-06-24 18:27:32.000000', NULL, 1),
(778338, 85245, 20779, '<td valign="top">Excellent shot taken. I think what keeps it from being scored higher by me is the lack of something "interesting" for my eye to look at and the fairly bland colors. Beautiful DOF also!</td>', 'Excellent shot taken. I think what keeps it from being scored higher by me is the lack of something "interesting" for my eye to look at and the fairly bland colors. Beautiful DOF also!', '2004-06-24 18:29:06.000000', NULL, 1),
(778340, 85263, 20779, '<td valign="top">Great shot for the local paper! I would score the next step up if there was just a little more punch of colors and less shadows, and that the line streaking down the man''s face is distracting to the overall quality.</td>', 'Great shot for the local paper! I would score the next step up if there was just a little more punch of colors and less shadows, and that the line streaking down the man''s face is distracting to the overall quality.', '2004-06-24 18:31:18.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(778343, 84756, 21621, '<td valign="top">Nice shot, unfourtunately the weather conditions did not give you the best light.  Might benefit from an icrease in brightness, also the the blue fence is a bit distracting.  Good Work.</td>', 'Nice shot, unfourtunately the weather conditions did not give you the best light.  Might benefit from an icrease in brightness, also the the blue fence is a bit distracting.  Good Work.', '2004-06-24 18:33:21.000000', NULL, 1),
(778345, 85321, 20779, '<td valign="top">This is a fun catch - the limo at McD''s! I think what is hurting you some here is the small size posted for us to see, a slightly tilted horizon, and the tree trunk disrupting our view. Maybe if you could have tried another angle that would make it a little more "interesting" along with perhaps avoiding some of the tree trunk (you may have had no choice, I know).</td>', 'This is a fun catch - the limo at McD''s! I think what is hurting you some here is the small size posted for us to see, a slightly tilted horizon, and the tree trunk disrupting our view. Maybe if you could have tried another angle that would make it a little more "interesting" along with perhaps avoiding some of the tree trunk (you may have had no choice, I know).', '2004-06-24 18:34:12.000000', NULL, 1),
(778353, 85295, 21621, '<td valign="top">Good shot, might benefit from a shorter headline, also I can imagine that this would  look better in color, but B&amp;W does fit this challenge.  Nice work.</td>', 'Good shot, might benefit from a shorter headline, also I can imagine that this would  look better in color, but B&W does fit this challenge.  Nice work.', '2004-06-24 18:38:17.000000', NULL, 1),
(778356, 85210, 3461, '<td valign="top">I like the drama of the shot (sky) but the boat could be better positioned so you can see more of it. 8</td>', 'I like the drama of the shot (sky) but the boat could be better positioned so you can see more of it. 8', '2004-06-24 18:40:07.000000', NULL, 1),
(778365, 84626, 3461, '<td valign="top">would work better as a backdrop. needs a human element.</td>', 'would work better as a backdrop. needs a human element.', '2004-06-24 18:44:10.000000', NULL, 1),
(778371, 85047, 21621, '<td valign="top">Good shot, might benefit from a shorter title, and possibly a deeper depth of field.  Nice work.</td>', 'Good shot, might benefit from a shorter title, and possibly a deeper depth of field.  Nice work.', '2004-06-24 18:51:46.000000', NULL, 1),
(778372, 84704, 5728, '<td valign="top">Fantastic action shot, the compostion has impact to it. The way the silohuette is sharply outlined by the brightness of the flames, and the way the body, specifically the head, curves slightly into the direction of the flames. I maybe would have given it a different title though, this one doesn''t really have that newspaper, headline kind of feel to it. I would have gone for something more dramatic. But it is still my favourite for the challenge (9)</td>', 'Fantastic action shot, the compostion has impact to it. The way the silohuette is sharply outlined by the brightness of the flames, and the way the body, specifically the head, curves slightly into the direction of the flames. I maybe would have given it a different title though, this one doesn''t really have that newspaper, headline kind of feel to it. I would have gone for something more dramatic. But it is still my favourite for the challenge (9)', '2004-06-24 18:52:59.000000', NULL, 1),
(778378, 84521, 18525, '<td valign="top">I take a lot of BB pictures as my kid plays as well so ... This shot would not make my keeper file unless it was the only capture I could muster.<br/>Why? well  focus the subject is not sharp a faster shutter speed was needed or a slower one for a motion blur. Lighting looks like it was in a good area but your position  captures the shadow part of it. Background is more in focus than the subject. Your auto focus cheated you from  a nice shot.<br/>If this is your child? If so take heart in that when I posted a BB picture of my kid in a challenge it was one of my lowest scores ever. But I did not care I was still proud.<br/>I scored you a 5.<br/>Good Luck<br/> <br/>Cheers<br/></td>', 'I take a lot of BB pictures as my kid plays as well so ... This shot would not make my keeper file unless it was the only capture I could muster.Why? well  focus the subject is not sharp a faster shutter speed was needed or a slower one for a motion blur. Lighting looks like it was in a good area but your position  captures the shadow part of it. Background is more in focus than the subject. Your auto focus cheated you from  a nice shot.If this is your child? If so take heart in that when I posted a BB picture of my kid in a challenge it was one of my lowest scores ever. But I did not care I was still proud.I scored you a 5.Good Luck Cheers', '2004-06-24 18:57:43.000000', NULL, 1),
(778380, 84692, 21621, '<td valign="top">Interesting idea, working with miniatures.  I might have tried something more dramatic, like a train wreck.</td>', 'Interesting idea, working with miniatures.  I might have tried something more dramatic, like a train wreck.', '2004-06-24 18:58:42.000000', NULL, 1),
(778382, 84628, 21621, '<td valign="top">Great shot, but your headline needs work.  Maybe "Mother and child barely escape inferno".  Nice work.</td>', 'Great shot, but your headline needs work.  Maybe "Mother and child barely escape inferno".  Nice work.', '2004-06-24 19:07:28.000000', NULL, 1),
(778384, 84757, 21621, '<td valign="top">Nice shot, might benefit from a slightly different angle to balance the negetive space in the upper right and lower left.  Good work.</td>', 'Nice shot, might benefit from a slightly different angle to balance the negetive space in the upper right and lower left.  Good work.', '2004-06-24 19:10:19.000000', NULL, 1),
(778388, 85319, 21362, '<td valign="top">Beautiful fireworks. I''d tighten the the crop so that the burst fill the frame completely. It would do two things: one, eliminate all the dead space that really does nothing for the photo and two, make the short crop on the top seem more appropriate.</td>', 'Beautiful fireworks. I''d tighten the the crop so that the burst fill the frame completely. It would do two things: one, eliminate all the dead space that really does nothing for the photo and two, make the short crop on the top seem more appropriate.', '2004-06-24 19:14:28.000000', NULL, 1),
(778389, 84086, 21362, '<td valign="top">Powerful image.</td>', 'Powerful image.', '2004-06-24 19:15:13.000000', NULL, 1),
(778390, 85175, 21621, '<td valign="top">Nice shot, but the headline needs work, dont have one off the top of my head, but this one just doesn''t sound like news.  Good work.</td>', 'Nice shot, but the headline needs work, dont have one off the top of my head, but this one just doesn''t sound like news.  Good work.', '2004-06-24 19:16:47.000000', NULL, 1),
(778394, 85005, 21621, '<td valign="top">Good Shot, a little out of focus, might benefit from more space to the right of the truck.  Nice work</td>', 'Good Shot, a little out of focus, might benefit from more space to the right of the truck.  Nice work', '2004-06-24 19:19:47.000000', NULL, 1),
(778412, 85174, 5728, '<td valign="top">She is a good model! The flash you have used has caused a harsh shadow on the wall behind her and flattened out her skin tones. I would have either bounced the flash of something reflective, or taken this photo closer to a window or somewhere where there is more available light.</td>', 'She is a good model! The flash you have used has caused a harsh shadow on the wall behind her and flattened out her skin tones. I would have either bounced the flash of something reflective, or taken this photo closer to a window or somewhere where there is more available light.', '2004-06-24 19:37:00.000000', NULL, 1),
(778426, 85312, 5728, '<td valign="top">Man this guy trains a lot by the looks of it :) Good action shot, free space in the direction he is running, maybe a touch more might have given him more movement space. Also the face area is a touch on the soft side. Otherwise good work.</td>', 'Man this guy trains a lot by the looks of it :) Good action shot, free space in the direction he is running, maybe a touch more might have given him more movement space. Also the face area is a touch on the soft side. Otherwise good work.', '2004-06-24 19:49:30.000000', NULL, 1),
(778427, 85221, 19608, '<td valign="top">This image is very formal and regal - as it should be.  Nice exposure, but the bright white on the right top is unfortunate.  Composition is ok but ever-so-slightly tilted.  Your title does indeed make it a news story..... it''s possible (many not too plausible though.)</td>', 'This image is very formal and regal - as it should be.  Nice exposure, but the bright white on the right top is unfortunate.  Composition is ok but ever-so-slightly tilted.  Your title does indeed make it a news story..... it''s possible (many not too plausible though.)', '2004-06-24 19:50:23.000000', NULL, 1),
(778430, 84320, 19608, '<td valign="top">Definitely a news event.  Colors are very nice but it does seem pretty busy.  Perhaps if you had knealed down and shot up more- you could have eliminated most of the spectators?</td>', 'Definitely a news event.  Colors are very nice but it does seem pretty busy.  Perhaps if you had knealed down and shot up more- you could have eliminated most of the spectators?', '2004-06-24 19:52:08.000000', NULL, 1),
(778434, 84636, 5728, '<td valign="top">You got yourself a fantastic position for this shot! Excellent action shot, captured at exactly the right instant with her hand still on the pole and half over the bar. I like the way you have slightly blurred out the body as you look down towards the feet, impressive effect. The head, hands and upper body are sharp and clear. Maybe the crop is a touch too tight, but other than that, nothing I can complain about!</td>', 'You got yourself a fantastic position for this shot! Excellent action shot, captured at exactly the right instant with her hand still on the pole and half over the bar. I like the way you have slightly blurred out the body as you look down towards the feet, impressive effect. The head, hands and upper body are sharp and clear. Maybe the crop is a touch too tight, but other than that, nothing I can complain about!', '2004-06-24 19:53:14.000000', NULL, 1),
(778436, 84729, 19608, '<td valign="top">As news, it is a real stretch - except for small town newspapers - but that''s OK!  Great idea, nice exposure and viewpoint.  The composition - with the massive OOF in the very foreground was not your best choice.  Crop the bottom to the wooden stick and I''d bet you will like it better.</td>', 'As news, it is a real stretch - except for small town newspapers - but that''s OK!  Great idea, nice exposure and viewpoint.  The composition - with the massive OOF in the very foreground was not your best choice.  Crop the bottom to the wooden stick and I''d bet you will like it better.', '2004-06-24 19:54:25.000000', NULL, 1),
(778492, 85175, 10263, '<td valign="top">This is cute. Very clear.  It would be a better shot if it didn''t have the parts of other people in it. The shoe in the bottom right is especially distracting.</td>', 'This is cute. Very clear.  It would be a better shot if it didn''t have the parts of other people in it. The shoe in the bottom right is especially distracting.', '2004-06-24 20:39:03.000000', NULL, 1),
(778499, 85306, 10263, '<td valign="top">I like this shot. I think it would have more impact if it was in color though.</td>', 'I like this shot. I think it would have more impact if it was in color though.', '2004-06-24 20:40:58.000000', NULL, 1),
