(779921, 85286, 19608, '<td valign="top">Too common a story in many places nowadays.  Print is pretty muddy with no pure white or black black.</td>', 'Too common a story in many places nowadays.  Print is pretty muddy with no pure white or black black.', '2004-06-25 20:16:13.000000', NULL, 1),
(779932, 84992, 23251, '<td valign="top">I just think this is a very busy photo, might have been better with one central focal point.</td>', 'I just think this is a very busy photo, might have been better with one central focal point.', '2004-06-25 20:27:07.000000', NULL, 1),
(779934, 85257, 23251, '<td valign="top">You probably didn''t have time to get the focus just right, shame.</td>', 'You probably didn''t have time to get the focus just right, shame.', '2004-06-25 20:29:02.000000', NULL, 1),
(779938, 84612, 23251, '<td valign="top">Wow that is amazing!</td>', 'Wow that is amazing!', '2004-06-25 20:30:32.000000', NULL, 1),
(779947, 85187, 23251, '<td valign="top">Not sure why but my eyes are drawn to the back spectators, maybe if it was cropped my focus would be more on the car. Still a nice pic though!</td>', 'Not sure why but my eyes are drawn to the back spectators, maybe if it was cropped my focus would be more on the car. Still a nice pic though!', '2004-06-25 20:39:26.000000', NULL, 1),
(779951, 85331, 23251, '<td valign="top">Its an ok photo but it simply shouts that its staged to me, maybe next time don''t have the person in the centre of the rug with their arms neatly at their side etc.</td>', 'Its an ok photo but it simply shouts that its staged to me, maybe next time don''t have the person in the centre of the rug with their arms neatly at their side etc.', '2004-06-25 20:43:38.000000', NULL, 1),
(779953, 85339, 23251, '<td valign="top">Mmmm I like it!</td>', 'Mmmm I like it!', '2004-06-25 20:44:28.000000', NULL, 1),
(779958, 85283, 23251, '<td valign="top">Pity about the hand rail and I had to look carefully to see that it was containers. Maybe if you had at least part of the sides of the containers it would have been more obvious to me.  Nice idea though.</td>', 'Pity about the hand rail and I had to look carefully to see that it was containers. Maybe if you had at least part of the sides of the containers it would have been more obvious to me.  Nice idea though.', '2004-06-25 20:50:12.000000', NULL, 1),
(779962, 84784, 16982, '<td valign="top">Good photo, but little detail can be made out at this distance from the trees.</td>', 'Good photo, but little detail can be made out at this distance from the trees.', '2004-06-25 20:54:16.000000', NULL, 1),
(779963, 85323, 23251, '<td valign="top">Nice pic I would think you put a lot of effort into it but missed the cord of the lamp hanging down oops! I like it but not sure if it would be newspaper stuff though!</td>', 'Nice pic I would think you put a lot of effort into it but missed the cord of the lamp hanging down oops! I like it but not sure if it would be newspaper stuff though!', '2004-06-25 20:54:18.000000', NULL, 1),
