(780643, 85055, 12611, '<td valign="top">This could also be titled "european dentists a rarity" or "How the hell do you tell the players from the referee''s in soccer." or "I should not have had the chili relleno- psssssst!!!!!!" one more thing- could they stuff any more advertisements onto the jerseys?</td>', 'This could also be titled "european dentists a rarity" or "How the hell do you tell the players from the referee''s in soccer." or "I should not have had the chili relleno- psssssst!!!!!!" one more thing- could they stuff any more advertisements onto the jerseys?', '2004-06-26 15:43:40.000000', NULL, 1),
(780644, 84264, 12611, '<td valign="top">file this one under "way too phallic for my taste" wow- I bet you smoke a cigarette, went through a tunnel in a train while eating a hotdog and talking to your mother after this shot.</td>', 'file this one under "way too phallic for my taste" wow- I bet you smoke a cigarette, went through a tunnel in a train while eating a hotdog and talking to your mother after this shot.', '2004-06-26 15:45:14.000000', NULL, 1),
