INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(780943, 84729, 2792, '<td valign="top">Could see this in the lifestyle section. =-)  Love the angle!</td>', 'Could see this in the lifestyle section. =-)  Love the angle!', '2004-06-26 23:32:44.000000', NULL, 1),
(780952, 85234, 2792, '<td valign="top">Nice pic, looks like a bridge that used to be in my hometown before they built a new one.  I''m not sure I like this in black and white.  I''m assuming you chose B&amp;W to feel more like a newspaper pic, but I think it would have been better in color because the crane (at least, I''m assuming its some sort of construction equipment) would have "popped" out more.  I had a difficult time seeing it.  Just IMHO. =-) 6</td>', 'Nice pic, looks like a bridge that used to be in my hometown before they built a new one.  I''m not sure I like this in black and white.  I''m assuming you chose B&W to feel more like a newspaper pic, but I think it would have been better in color because the crane (at least, I''m assuming its some sort of construction equipment) would have "popped" out more.  I had a difficult time seeing it.  Just IMHO. =-) 6', '2004-06-26 23:40:54.000000', NULL, 1),
(780985, 84522, 10082, '<td valign="top">Great capture ! Looks just like what you would see on the front page :)</td>', 'Great capture ! Looks just like what you would see on the front page :)', '2004-06-27 00:29:49.000000', NULL, 1),
(780986, 85291, 3599, '<td valign="top">I like the grain effect, it does give the feel of a newspaper.  The picture itself isn''t very interesting though.  Could you have gone with a different angle?  I know you are trying to show the beach and ATV together but readers trust headlines(sometimes).  It may not have been necessary to show the beach as much.  I think an angle looking up from the left front tire with the police officer looking down would have been cool.  It would make him look more authoritive.  Just a thought.  I really like the title, one of the better ones of the challenge.   Good work and good luck in the challenge:)</td>', 'I like the grain effect, it does give the feel of a newspaper.  The picture itself isn''t very interesting though.  Could you have gone with a different angle?  I know you are trying to show the beach and ATV together but readers trust headlines(sometimes).  It may not have been necessary to show the beach as much.  I think an angle looking up from the left front tire with the police officer looking down would have been cool.  It would make him look more authoritive.  Just a thought.  I really like the title, one of the better ones of the challenge.   Good work and good luck in the challenge:)', '2004-06-27 00:30:36.000000', NULL, 1),
