(782693, 84469, 2792, '<td valign="top">Great shot, love the lighting!</td>', 'Great shot, love the lighting!', '2004-06-28 12:31:56.000000', NULL, 1),
(782733, 85304, 11895, '<td valign="top">very well executed capture but it looks more like a fight is about  to break out than a celebration;  I doubt a newspaper would run this, at least not under the title you have used, maybe something like "Captain demands respect from undisciplined players" would have been perceived by the voters as more appropriate to the photo</td>', 'very well executed capture but it looks more like a fight is about  to break out than a celebration;  I doubt a newspaper would run this, at least not under the title you have used, maybe something like "Captain demands respect from undisciplined players" would have been perceived by the voters as more appropriate to the photo', '2004-06-28 12:56:20.000000', NULL, 1),
(782845, 84429, 19751, '<td valign="top">the flames look out of focus</td>', 'the flames look out of focus', '2004-06-28 13:53:14.000000', NULL, 1),
(782847, 85002, 19751, '<td valign="top">nice picture, but the title doesnt really fit the picture. Somewhat captures the idea though.</td>', 'nice picture, but the title doesnt really fit the picture. Somewhat captures the idea though.', '2004-06-28 13:54:04.000000', NULL, 1),
