(783598, 85221, 16488, '<td valign="top">Given the "headline," I think it would be better if the entire uniform were shown.</td>', 'Given the "headline," I think it would be better if the entire uniform were shown.', '2004-06-28 19:51:56.000000', NULL, 1),
