(784065, 85151, 22480, '<td valign="top">Really nice shot.  I would have liked the colors outside the train to be slightly warmer, but that would have been hard to achieve within the editing rules.  Good job with the framing, although I might have tried to get the top of the man''s hand in the frame as well.</td>', 'Really nice shot.  I would have liked the colors outside the train to be slightly warmer, but that would have been hard to achieve within the editing rules.  Good job with the framing, although I might have tried to get the top of the man''s hand in the frame as well.', '2004-06-28 23:55:16.000000', NULL, 1),
(784066, 84636, 22480, '<td valign="top">Totally beautiful shot.  I love the feel of action.  This is really really great.  My only nitpick is that I''ve never seen a newspaper include a frame like that, but it is very effective.</td>', 'Totally beautiful shot.  I love the feel of action.  This is really really great.  My only nitpick is that I''ve never seen a newspaper include a frame like that, but it is very effective.', '2004-06-28 23:56:20.000000', NULL, 1),
(784068, 85333, 22480, '<td valign="top">Nice job with the framing.  I like the model''s hat too.</td>', 'Nice job with the framing.  I like the model''s hat too.', '2004-06-28 23:56:49.000000', NULL, 1),
(784116, 84961, 23027, '<td valign="top">We actually do have a punster who writes headines for our local paper.  Great job and great headline.</td>', 'We actually do have a punster who writes headines for our local paper.  Great job and great headline.', '2004-06-29 00:47:04.000000', NULL, 1),
