(784371, 85210, 11410, '<td valign="top">wow!  lovely shot - beautiful sky (makes the sea look kinda grimy though, doesn''t it!)</td>', 'wow!  lovely shot - beautiful sky (makes the sea look kinda grimy though, doesn''t it!)', '2004-06-29 05:47:40.000000', NULL, 1),
