(784913, 85212, 23614, '<td valign="top">Intense. I like it.</td>', 'Intense. I like it.', '2004-06-29 14:16:14.000000', NULL, 1),
(784925, 84646, 22922, '<td valign="top">This is one of the best uses of a casual photograph ever.  You were able to not only see the humor yourself, but show it to your audience, a major feat on a site that frowns on "snapshot"-like images.  Great Job!</td>', 'This is one of the best uses of a casual photograph ever.  You were able to not only see the humor yourself, but show it to your audience, a major feat on a site that frowns on "snapshot"-like images.  Great Job!', '2004-06-29 14:27:03.000000', NULL, 1),
(784935, 84756, 8159, '<td valign="top">The blue temporary fence in the background is distracting. I hate those things; they always end up in my viewfinder too. One option to address that issue and improve on the composition would be to get down lower and zoom in on the face of the gentleman in the foreground. This subject matter has some good potential, and getting "in close" would focus attention.</td>', 'The blue temporary fence in the background is distracting. I hate those things; they always end up in my viewfinder too. One option to address that issue and improve on the composition would be to get down lower and zoom in on the face of the gentleman in the foreground. This subject matter has some good potential, and getting "in close" would focus attention.', '2004-06-29 14:35:43.000000', NULL, 1),
(784948, 84636, 4400, '<td valign="top">Fín mynd en ég hefði kosið að hafa hana á lengri vegin<br/> takk fyrir comentið:O)</td>', 'Fín mynd en ég hefði kosið að hafa hana á lengri vegin takk fyrir comentið:O)', '2004-06-29 14:41:06.000000', NULL, 1),
