INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(785046, 85158, 23449, '<td valign="top">This would have been better if the photographer''s vantage point had been shifte a bit left, with a little more of the line of cars visible in the right section of the photo.  I''m very afraid the photographer was driving while shooting.</td>', 'This would have been better if the photographer''s vantage point had been shifte a bit left, with a little more of the line of cars visible in the right section of the photo.  I''m very afraid the photographer was driving while shooting.', '2004-06-29 15:43:51.000000', NULL, 1),
